type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    assert!(shape.len() == 2, "Shape must have exactly two dimensions");
    let rows = shape[0] as usize;
    let cols = shape[1] as usize;
    let len = a.len();
    
    assert!(rows > 0 && cols > 0, "Dimensions must be positive");
    assert!(len > 0, "Input array must be non-empty");
    assert!(
        len == rows || len == cols,
        "Array length must match one of the dimensions"
    );

    let mut result = Vec::with_capacity(rows);
    if len == rows {
        // Broadcast as column vector: each a[i] fills row i
        for i in 0..rows {
            let v = a[i];
            let mut row = Vec::with_capacity(cols);
            for _ in 0..cols {
                row.push(v);
            }
            result.push(row);
        }
    } else {
        // Broadcast as row vector: each row is a clone of `a`
        for _ in 0..rows {
            result.push(a.clone());
        }
    }

    result
}

